package main

import "fmt"

func push(s []int, v int) []int {
	s = append(s, v) // 返回「新头」,但这里丢掉了
	fmt.Println("函数内:", len(s), cap(s), s)
	return s
}

func main() {
	// 情形 A:cap 够(3 < 5)
	a := make([]int, 3, 5)
	copy(a, []int{1, 2, 3})
	push(a, 9)
	fmt.Println("情形A 调用方:", len(a), cap(a), a) // len 仍是 3

	// 情形 B:cap 正好用满
	b := []int{1, 2, 3} // len=3 cap=3
	push(b, 9)
	fmt.Println("情形B 调用方:", len(b), cap(b), b) // 完全不变

	// 情形 C:正确写法——接收返回值
	c := []int{1, 2, 3}
	c = push(c, 9)
	fmt.Println("情形C 调用方:", len(c), cap(c), c) // 4 [1 2 3 9]
}

