package main

import (
	"fmt"
	"sync"
)

func main() {
	defer func() {
		if r := recover(); r != nil {
			fmt.Println("recovered:", r)
		}
	}()

	m := make(map[int]int)
	var wg sync.WaitGroup
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for j := 0; j < 100000; j++ {
				m[j] = j // 两个 goroutine 同时写
			}
		}(i)
	}
	wg.Wait()
	fmt.Println("done", len(m))
}

package main

import (
	"fmt"
	"unicode/utf8"
)

func main() {
	s := "a中b"
	fmt.Println(len(s))                        // 5
	fmt.Println(utf8.RuneCountInString(s))     // 3

	for i, r := range s {
		fmt.Printf("i=%d r=%c runeLen=%d\n", i, r, utf8.RuneLen(r))
	}
	// i=0 r=a runeLen=1
	// i=1 r=中 runeLen=3   <- 索引跳了 3
	// i=4 r=b runeLen=1

	// 按字节遍历:中文会被拆成 3 个非法字节
	for i := 0; i < len(s); i++ {
		fmt.Printf("%d:%x ", i, s[i])
	}
	// 0:61 1:e4 2:b8 3:ad 4:62   <- 1~3 是「中」的三个字节

	// 错误示范:用 len 当字符数去切最后一个字符
	// fmt.Println(s[len(s)-1:])  // 输出 "b",但若结尾是中文就切出乱码
}

package main

import "fmt"

// A:具名返回值 + defer 修改 -> 2
func a() (x int) {
	defer func() { x++ }()
	return 1
}

// B:匿名返回值 + defer 改局部变量 -> 1
func b() int {
	var x = 1
	defer func() { x++ }()
	return x
}

// C:具名返回值 + defer 修改,但 return 显式赋值 -> 2
func c() (x int) {
	defer func() { x *= 10 }()
	return 3
}

// D:defer 参数在注册时求值 -> 打印 0,返回 1
func d() (x int) {
	defer fmt.Println("defer sees x =", x) // 注册时 x 还是 0
	x = 1
	return
}

func main() {
	fmt.Println(a(), b(), c()) // 2 1 30
	fmt.Println(d())           // defer sees x = 0 \n 1
}

package main

import "fmt"

// 正确:defer 的函数体内直接调用
func try(name string, f func()) {
	defer func() {
		if r := recover(); r != nil {
			fmt.Printf("[%s] recovered: %v\n", name, r)
		}
	}()
	f()
}

func main() {
	try("ok", func() { panic("boom") })

	// 无效 1:defer recover() —— recover 被当参数求值,返回 nil 后丢弃
	func() {
		defer recover()
		panic("not caught")
	}()
}

