package main

import (
	"fmt"
	"sync"
)

func main() {
	// 场景 A：goroutine 抓住循环变量
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			fmt.Print(i, " ")
		}()
	}
	wg.Wait()
	fmt.Println() // go.mod < 1.22：3 3 3（顺序不定）；>= 1.22：0/1/2 三个数（顺序不定）

	// 场景 B：range 给的是元素副本，改不动原切片
	type P struct{ Name string }
	ps := []P{{"a"}, {"b"}}
	for _, p := range ps {
		p.Name = "X" // 改的是副本，ps 不受影响
	}
	fmt.Println(ps) // [{a} {b}]

	for i := range ps {
		ps[i].Name = "Y" // 拿下标才改得动
	}
	fmt.Println(ps) // [{Y} {Y}]

	// 场景 C：range 时 append，不会多迭代
	s := []int{1, 2, 3}
	for _, v := range s {
		if v == 1 {
			s = append(s, 99)
		}
		fmt.Print(v, " ") // 1 2 3，长度在开始时已经定死
	}
	fmt.Println("| len =", len(s)) // len = 4
}

package main

import "fmt"

type ByteSize float64

const (
	_           = iota             // 0 被丢弃,但占了 0 号
	KB ByteSize = 1 << (10 * iota) // iota=1 -> 1024
	MB                             // 复用表达式,iota=2 -> 1<<20
	GB                             // iota=3 -> 1<<30
	TB                             // iota=4 -> 1<<40
)

const (
	A, B = iota, iota * 2 // 同一行 iota 相同:A=0, B=0
	C, D                  // iota=1:A? 不,是 C=1, D=2
)

const (
	X = iota // 新 const 块,重置为 0
	Y
	Z
)

func main() {
	fmt.Println(KB, MB, GB)          // 1024 1.048576e+06 1.073741824e+09
	fmt.Println(A, B, C, D)          // 0 0 1 2
	fmt.Println(X, Y, Z)             // 0 1 2
}

package main

import "fmt"

// 写法一:泛型,编译期实例化,零断言零反射
func Map[T any, R any](in []T, f func(T) R) []R {
	out := make([]R, len(in))
	for i, v := range in {
		out[i] = f(v)
	}
	return out
}

// 写法二:interface{},要断言,且在 Go 1.18 前无法表达「元素类型」
func MapAny(in []any, f func(any) any) []any {
	out := make([]any, len(in))
	for i, v := range in {
		out[i] = f(v)
	}
	return out
}

// 约束示例:~int 让 MyInt 也满足
type MyInt int

type Number interface {
	~int | ~int64 | ~float64
}

func Sum[T Number](xs []T) T {
	var s T
	for _, x := range xs {
		s += x
	}
	return s
}

func main() {
	fmt.Println(Map([]int{1, 2, 3}, func(x int) string { return fmt.Sprint(x * 2) }))
	fmt.Println(Sum([]MyInt{1, 2, 3})) // ~ 让 MyInt 通过约束
}

package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found")

type QueryError struct {
	Table string
	Err   error
}

func (e *QueryError) Error() string { return e.Table + ": " + e.Err.Error() }
func (e *QueryError) Unwrap() error { return e.Err }

func good() error {
	return fmt.Errorf("load user: %w", ErrNotFound) // 建链
}

func bad() error {
	return fmt.Errorf("load user: %v", ErrNotFound) // 断链!
}

func main() {
	fmt.Println(errors.Is(good(), ErrNotFound)) // true
	fmt.Println(errors.Is(bad(), ErrNotFound))  // false  <- 隐蔽 bug

	// errors.As 取具体类型
	err := fmt.Errorf("query: %w", &QueryError{Table: "users", Err: ErrNotFound})
	var qe *QueryError
	if errors.As(err, &qe) {
		fmt.Println("table =", qe.Table) // users
	}
}

package main

import "fmt"

type MyErr struct{ Msg string }

func (e *MyErr) Error() string { return e.Msg }

// 坏:返回了「装着 nil *MyErr 的 error 接口」
func bad() error {
	var e *MyErr
	return e
}

// 好:显式返回字面量 nil
func good() error {
	var e *MyErr
	if e == nil {
		return nil
	}
	return e
}

func main() {
	fmt.Println(bad() == nil)  // false  <- 坑
	fmt.Println(good() == nil) // true

	var e *MyErr
	var i error = e
	fmt.Printf("i == nil ? %v\n", i == nil) // false
	fmt.Printf("i 的动态类型: %T\n", i)      // *main.MyErr

	// 想看「里面是不是 nil 指针」只能先断言
	if p, ok := i.(*MyErr); ok && p == nil {
		fmt.Println("确实是一个 nil 指针装进了接口")
	}
}

package main

import (
	"fmt"
	"io"
	"strings"
)

func describe(i any) string {
	switch v := i.(type) {
	case nil:
		return "nil 接口"
	case int:
		return fmt.Sprintf("int, 平方=%d", v*v)
	case string:
		return fmt.Sprintf("string, 长度=%d", len(v))
	case io.Reader:
		return "实现了 io.Reader"
	default:
		return fmt.Sprintf("其它类型 %T", v)
	}
}

func main() {
	fmt.Println(describe(nil))                     // nil 接口
	fmt.Println(describe(3))                       // int, 平方=9
	fmt.Println(describe("abc"))                   // string, 长度=3
	fmt.Println(describe(strings.NewReader("x")))  // 实现了 io.Reader

	var i any = 42

	// 危险:失败即 panic
	// s := i.(string)

	// 安全:双返回值
	s, ok := i.(string)
	fmt.Println(s, ok) // "" false

	// 断言到接口:检查「能力」而不是「身份」
	if _, ok := i.(io.Reader); !ok {
		fmt.Println("42 不是 Reader")
	}
}

package main

import (
	"fmt"
	"unsafe"
)

func main() {
	// 1) 大小确实是 0
	fmt.Println(unsafe.Sizeof(struct{}{})) // 0

	// 2) 两个空结构体的地址可能相同
	a, b := struct{}{}, struct{}{}
	fmt.Println(&a == &b) // true 或 false 都可能(规范不保证)

	// 3) map[T]struct{} 当集合
	set := make(map[string]struct{})
	set["go"] = struct{}{}
	if _, ok := set["go"]; ok {
		fmt.Println("存在")
	}

	// 4) chan struct{} 当信号:close 即广播
	done := make(chan struct{})
	go func() {
		fmt.Println("worker 完成")
		close(done) // 广播,所有阻塞在 <-done 的 goroutine 一起醒
	}()
	<-done
	fmt.Println("main 继续")

	// 5) 只关心次数的循环
	for range make([]struct{}, 3) {
		fmt.Print("x")
	}
	fmt.Println()
}

package main

import (
	"fmt"
	"unsafe"
)

type Bad struct {
	A int8
	B int64
	C int8
}

type Good struct {
	B int64
	A int8
	C int8
}

func main() {
	fmt.Println(unsafe.Sizeof(Bad{}), unsafe.Alignof(Bad{}))   // 24 8
	fmt.Println(unsafe.Sizeof(Good{}), unsafe.Alignof(Good{})) // 16 8

	fmt.Println(unsafe.Offsetof(Bad{}.A), unsafe.Offsetof(Bad{}.B), unsafe.Offsetof(Bad{}.C))
	// 0 8 16  <- 1~7 是填充

	fmt.Println(unsafe.Offsetof(Good{}.B), unsafe.Offsetof(Good{}.A), unsafe.Offsetof(Good{}.C))
	// 0 8 9   <- 没有中间填充

	// 嵌套结构体:内层对齐值也参与外层计算
	type Nested struct {
		X int8
		G Good // 对齐值 8
	}
	fmt.Println(unsafe.Sizeof(Nested{})) // 24:1 + 7 填充 + 16
}
